/* The company a buyer bought for, on a checkout that ships (round chk-1021): `commerce_checkouts.business_details`, the company's legal name, tax number and address as the website's checkout checked them (lib/checkout/business.ts), only where Settings › Checkout › Company invoices is on (part 256). The paid checkout writes it on every order line it becomes (`orders.business_details`, part 36), as a basket of downloads already does, so the invoice, the receipt and the seller's copy of the invoice are made out to the company for a cart that ships, or ships with downloads in it. Before this a shipped cart's company was checked and then dropped. Adds one column, empty on every checkout already there; changes no rows. Written by the server only, as every checkout column is. Needs part 78's table, and skips with a notice where it is not there. Until it runs, a shipped order is made as before, without the company. */
DO $do$ BEGIN IF to_regclass('public.commerce_checkouts') IS NULL THEN RAISE NOTICE 'checkout company: commerce_checkouts is not there yet (part 78).'; RETURN; END IF; ALTER TABLE public.commerce_checkouts ADD COLUMN IF NOT EXISTS business_details jsonb; ALTER TABLE public.commerce_checkouts DROP CONSTRAINT IF EXISTS commerce_checkouts_business_details_shape; ALTER TABLE public.commerce_checkouts ADD CONSTRAINT commerce_checkouts_business_details_shape CHECK (business_details IS NULL OR (jsonb_typeof(business_details) = 'object' AND pg_column_size(business_details) <= 4096)) NOT VALID; END $do$;
notify pgrst, 'reload schema';
